use verus::*;

verus! {

    /// Given a non‐empty array `a` of signed 8‐bit integers,
    /// returns the maximum value in `a`.  The returned value
    /// is guaranteed to be an element of `a`, is at least as large
    /// as every element of `a`, and its first occurrence in `a`
    /// is at the smallest index at which that value appears.
    fn amax(a: Vec<i8>) -> (res: i8)
        requires
            a.len() > 0
        ensures
            // there is some index `idx` witnessing the first occurrence
            // of the maximum `res`
            exists(|idx: usize|
                idx < a.len() &&
                // res is exactly a[idx]
                res == a[idx] &&
                // every element of a is ≤ res
                forall(|j: usize| j < a.len() ==> a[j] <= res) &&
                // no occurrence of res before idx
                forall(|j: usize| j < idx    ==> a[j] < res)
            )
    {
        let n = a.len();

        // We'll track the index of the largest-seen-so-far element.
        let mut max_idx: usize = 0;
        let mut i: usize = 1;

        // Invariant at each step i:
        //  1 <= i <= n
        // max_idx < i
        // For all j < i, a[j] ≤ a[max_idx]
        // For all j < max_idx, a[j] < a[max_idx]
        while i < n
            invariant 1 <= i && i <= n
            invariant max_idx < i
            invariant forall(|j: usize| j < i          ==> a[j] <= a[max_idx])
            invariant forall(|j: usize| j < max_idx   ==> a[j] <  a[max_idx])
            decreases n - i
        {
            if a[i] > a[max_idx] {
                max_idx = i;
            }
            i += 1;
        }

        // At this point i == n, so max_idx < n
        assert(max_idx < n);

        // Define the result and prove the post‐condition by
        // choosing idx = max_idx as the witness.
        let res = a[max_idx];
        // res is ≥ every element of a
        assert(forall(|j: usize| j < n ==> a[j] <= res));
        // no earlier index has value = res
        assert(forall(|j: usize| j < max_idx ==> a[j] < res));
        // package up the existential
        assert(exists(|idx: usize|
            idx == max_idx &&
            idx < n &&
            res == a[idx] &&
            forall(|j: usize| j < n   ==> a[j] <= res) &&
            forall(|j: usize| j < idx ==> a[j] <  res)
        ));

        res
    }

}